import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, ElementRef, HostListener, ViewChild } from '@angular/core';
import { TableModule } from 'primeng/table';
import { ButtonModule } from 'primeng/button';
import { TooltipModule } from 'primeng/tooltip';
import { RippleModule } from 'primeng/ripple';
import { PaginatorComponent } from '../../../../shared/components/paginator/paginator.component';
import { Router, RouterModule } from '@angular/router';
import { PagedResponse } from '../../../applicants/models/api-response.model';
import { ArchiveModel } from '../../models/archive.model';
import { ArchiveService } from '../../services/archive';
import { NgbModal } from '@ng-bootstrap/ng-bootstrap';
import { Result } from '../../../../shared/models/result.model';
import { EditArchive } from '../edit-archive/edit-archive';
import { DataSharingService } from '../../../../shared/services/data-sharing';
import { GregorianDatePipe } from '../../../../shared/pipes/gregorian-date.pipe';
import { Table } from 'primeng/table';
import { ResetFiltersButtonComponent } from '../../../../shared/components/reset-filters-button/reset-filters-button.component';
@Component({
  selector: 'app-archive-list',
  imports: [PaginatorComponent, TableModule, ButtonModule, TooltipModule, RippleModule, CommonModule, RouterModule, GregorianDatePipe, ResetFiltersButtonComponent],
  templateUrl: './archive-list.html',
  styleUrl: './archive-list.scss'
})
export class ArchiveList {
archives: ArchiveModel[] = [];
  loading = true;
  globalFilter: string = '';

  page = 1;
  rowsPerPage = 10;
  totalRecords = 0;
  tableHeight = '300px';
  @ViewChild('table') table?: Table;
  @ViewChild('searchInput') searchInput?: ElementRef<HTMLInputElement>;

  constructor(
    private archiveService: ArchiveService,
    private cdr: ChangeDetectorRef,
    private router: Router,
    private modalService: NgbModal,
    private dataSharingService: DataSharingService 
  ) { }

  ngOnInit(): void {
    this.loadArchives();
  }

  loadArchives() {
    this.archiveService.getArchives$(this.page, this.rowsPerPage, this.globalFilter)
      .subscribe({
        next: (res: PagedResponse<ArchiveModel>) => {
          // ترتيب البيانات حسب المعرف (archiveID) تنازلياً - الأحدث أولاً
          // نسخ المصفوفة وترتيبها حسب archiveID تنازلياً (الأكبر = الأحدث)
          const sortedItems = [...res.items].sort((a, b) => {
            // الترتيب الأساسي حسب archiveID تنازلياً (الأكبر = الأحدث)
            return b.archiveID - a.archiveID;
          });
          this.archives = sortedItems;
          this.totalRecords = res.totalCount;
          this.loading = false;
        },
        error: (err) => {
          console.error('Error fetching archives', err);
          this.loading = false;
        }
      });
  }

 openArchiveDetails(archive: ArchiveModel) {
    this.router.navigate(['/applicants', archive.applicantFileNumber], { state: { archive: archive } });
  }

  onPageChange(newPage: number) {
    this.page = newPage;
    this.loadArchives();
  }

  onPageSizeChange(newSize: number) {
    this.rowsPerPage = newSize;
    this.page = 1;
    this.loadArchives();
  }

  onFilterChange(event: Event) {
    const value = (event.target as HTMLInputElement).value.toLowerCase().trim();
    this.globalFilter = value;
    this.page = 1;
    this.loadArchives();
  }


   openEditArchive(archive:ArchiveModel) {
    const modalRef = this.modalService.open(EditArchive, {
      size: 'lg',
      backdrop: 'static',
      keyboard: false,
      centered: true
    });
    modalRef.componentInstance.archive = archive;
     modalRef.componentInstance.archiveUpdated.subscribe(() => {
    this.loadArchives();
  });
  }

  ngAfterViewInit() {
    this.tableHeight = this.calculateTableHeight();
    this.cdr.detectChanges();
  }

  calculateTableHeight(): string {
    return window.innerHeight - 200 + 'px';
  }

  @HostListener('window:resize')
  onResize() {
    this.setTableHeight();
  }

  setTableHeight() {
    const screenHeight = window.innerHeight;
    const reservedSpace = 220;
    this.tableHeight = (screenHeight - reservedSpace) + 'px';
  }

  resetFilters(): void {
    this.globalFilter = '';
    this.page = 1;
    if (this.searchInput) {
      this.searchInput.nativeElement.value = '';
    }
    if (this.table) {
      this.table.first = 0;
      this.table.clear();
    }
    this.loadArchives();
  }
}
